#include <stdio.h>

int uniquePaths(int m, int n) {
    int k = (m - 1 < n - 1) ? (m - 1) : (n - 1);
    int total = m + n - 2;
    long long result = 1;
    for (int i = 1; i <= k; ++i) {
        result = result * (total - k + i) / i;
    }
    return (int)result;
}

int main(void) {
    int m, n;
    if (scanf(" [ %d , %d ]", &m, &n) != 2) return 0;
    printf("%d\n", uniquePaths(m, n));
    return 0;
}

