using namespace std;

class Solution {
public:
    int uniquePaths(int m, int n) {
        int k = min(m - 1, n - 1);
        int total = m + n - 2;
        long long result = 1;
        for (int i = 1; i <= k; ++i) {
            result = result * (total - k + i) / i;
        }
        return static_cast<int>(result);
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    if (!getline(cin, line)) return 0;

    for (char &c : line) {
        if (c == '[' || c == ']' || c == ',') c = ' ';
    }

    stringstream ss(line);
    int m, n;
    ss >> m >> n;
    cout << Solution().uniquePaths(m, n) << '\n';
    return 0;
}

